// PLACEHOLDER — not wired into the flow yet.
// Once the user adds a Motion API key (and/or Google Calendar OAuth), fetch:
//   1. Today's tasks due  -> Motion API  GET https://api.usemotion.com/v1/tasks  (header X-API-Key)
//   2. Today's calendar events -> Google Calendar node (events:getAll, timeMin/timeMax = today)
// Then merge those arrays into the item passed to 'Build Brief Prompt' so Cosmo can add
// a 'Tasks due' and 'On the calendar' section to the morning brief.
// Return shape suggestion:  return [{ json: { tasks: [...], events: [...] } }];
return $input.all();

// Cosmo daily-brief prompt builder.
// Pulls top headlines from the SearXNG result and assembles a single Ollama /generate prompt.
const items = $input.all();
const sx = items[0] && items[0].json ? items[0].json : {};
const results = Array.isArray(sx.results) ? sx.results : [];

// Take up to 6 distinct, titled results; trim to keep the prompt small.
const seen = new Set();
const headlines = [];
for (const r of results) {
  const title = (r && r.title ? String(r.title) : '').trim();
  if (!title || seen.has(title)) continue;
  seen.add(title);
  const src = (r && r.engine ? String(r.engine) : '').trim();
  headlines.push(src ? `${title} (${src})` : title);
  if (headlines.length >= 6) break;
}
const headlinesBlock = headlines.length
  ? headlines.map((h, i) => `${i + 1}. ${h}`).join('\n')
  : '(no headlines retrieved — note this briefly and still produce a brief)';

// Today's date, Europe/Berlin, human readable.
const today = new Date().toLocaleDateString('en-GB', {
  timeZone: 'Europe/Berlin',
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const persona = `You are Cosmo, chief of staff to a solo software-agency founder (Europe/Berlin). You operate inside Telegram, so be extremely concise and mobile-readable: lead with the answer or the action, no preamble, no sign-off. Use short bullets. Surface only what matters; suppress noise. Times are Europe/Berlin. Before any irreversible or external action (sending a client message, issuing an invoice, deleting), summarize the action in one line and ask \"Confirm? (yes/no)\". When routing a command, pick exactly one destination and state it. Never be chatty.`;

const task = `Write today's morning brief. Use PLAIN TEXT only (no markdown symbols like *, #, or backticks). Keep it under 2500 characters total.\n\nStructure exactly:\nLine 1: a one-line greeting that includes today's date: ${today}.\nThen a line that says: Today\nThen 3-4 bullet lines (each starting with \"- \"), one per headline, each a tight one-line takeaway from the headlines below (rephrase, do not just copy; skip duplicates and pure noise).\nThen one blank line.\nThen a single motivating one-liner to start the day.\n\nHeadlines:\n${headlinesBlock}`;

const prompt = `${persona}\n\n${task}`;

return [{ json: { model: 'qwen3:8b', prompt } }];
